/**
 * Shared AWS Secrets Manager helpers, used by bruno-electron and bruno-cli.
 *
 * The AWS SDK is `require`d lazily so importing this module never fails when the optional
 * dependency isn't installed. Proxy/TLS is environment-specific, so callers pass a
 * `resolveAgents(url)` that returns `{ httpAgent, httpsAgent }` for a request URL.
 */

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { buildResolveAgents } from '../resolve-agents';
import type { SecretManagerNetworkConfig } from '../resolve-agents';

export interface AwsSecretsManagerConfig {
  authMethod?: string;
  profileName?: string;
  accessKeyId?: string;
  secretAccessKey?: string;
  sessionToken?: string;
  region?: string;
}

export interface AwsSecretResult {
  secretName: string;
  data?: any;
  error?: string;
}

const awsEndpointForRegion = (region?: string) => `https://secretsmanager.${region}.amazonaws.com`;

// Resolve AWS credentials from a profile (aws-cli) or from manually supplied keys.
export const resolveAwsCredentials = async (awsConfig: AwsSecretsManagerConfig = {}) => {
  if (awsConfig.authMethod === 'aws-cli') {
    const { fromIni } = require('@aws-sdk/credential-providers');
    try {
      const credentialsProvider = fromIni({ profile: awsConfig.profileName || 'default', ignoreCache: true });
      return await credentialsProvider();
    } catch (profileError: any) {
      const profileName = awsConfig.profileName || 'default';
      throw new Error(`Failed to resolve credentials from profile '${profileName}': ${profileError.message}`);
    }
  }
  const credentials: any = {
    accessKeyId: awsConfig.accessKeyId,
    secretAccessKey: awsConfig.secretAccessKey
  };
  if (awsConfig.sessionToken) {
    credentials.sessionToken = awsConfig.sessionToken;
  }
  return credentials;
};

// Fetch each named secret from AWS Secrets Manager. JSON string values are parsed into objects.
// Errors are returned per-secret so one failure doesn't abort the rest.
export const fetchAwsSecretsManagerSecrets = async ({
  awsConfig,
  secretNames,
  networkConfig
}: {
  awsConfig: AwsSecretsManagerConfig;
  secretNames: string[];
  networkConfig?: SecretManagerNetworkConfig;
}): Promise<AwsSecretResult[]> => {
  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const { NodeHttpHandler } = require('@smithy/node-http-handler');

  const resolveAgents = buildResolveAgents(networkConfig);
  const credentials = await resolveAwsCredentials(awsConfig);
  const { httpAgent, httpsAgent } = await resolveAgents(awsEndpointForRegion(awsConfig.region));
  const client = new SecretsManagerClient({
    region: awsConfig.region,
    credentials,
    requestHandler: new NodeHttpHandler({ httpAgent, httpsAgent })
  });

  return Promise.all(
    (secretNames || []).map(async (secretName): Promise<AwsSecretResult> => {
      try {
        const response = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
        let data: any;
        try {
          data = JSON.parse(response.SecretString);
        } catch (_) {
          data = response.SecretString;
        }
        return { secretName, data };
      } catch (error: any) {
        return { secretName, error: error?.message || 'Unknown error' };
      }
    })
  );
};

export const awsWhoami = async ({
  config,
  networkConfig
}: {
  config: { awsConfig: AwsSecretsManagerConfig };
  networkConfig?: SecretManagerNetworkConfig;
}): Promise<{ status: string; message: string }> => {
  const { SecretsManagerClient, ListSecretsCommand } = require('@aws-sdk/client-secrets-manager');
  const { NodeHttpHandler } = require('@smithy/node-http-handler');

  try {
    const resolveAgents = buildResolveAgents(networkConfig);
    const credentials = await resolveAwsCredentials(config.awsConfig);
    const { httpAgent, httpsAgent } = await resolveAgents(awsEndpointForRegion(config.awsConfig.region));
    const client = new SecretsManagerClient({
      region: config.awsConfig.region,
      credentials,
      requestHandler: new NodeHttpHandler({ httpAgent, httpsAgent })
    });
    await client.send(new ListSecretsCommand({ MaxResults: 1 }));
    return { status: 'success', message: 'AWS credentials are valid' };
  } catch (error: any) {
    throw new Error(error.message || 'Failed to validate AWS credentials');
  }
};

// Read the unique set of profile names from the user's ~/.aws config and credentials files.
export const getAvailableAWSProfiles = (): string[] => {
  try {
    const awsConfigPath = path.join(os.homedir(), '.aws', 'config');
    const awsCredentialsPath = path.join(os.homedir(), '.aws', 'credentials');

    const profiles = new Set<string>();
    let hasAnyProfiles = false;

    const readAndParseAWSFile = (filePath: string, isConfigFile = false): boolean => {
      try {
        if (!fs.existsSync(filePath)) {
          return false;
        }
        const content = fs.readFileSync(filePath, 'utf8');
        if (!content || content.trim() === '') {
          return false;
        }
        const pattern = isConfigFile ? /\[profile\s+([^\]]+)\]/g : /\[([^\]]+)\]/g;
        const matches = content.match(pattern);
        if (matches && matches.length > 0) {
          matches.forEach((match) => {
            const profileName = match.replace(/\[(?:profile\s+)?/, '').replace(/\]/, '').trim();
            if (profileName && profileName.length > 0) {
              profiles.add(profileName);
            }
          });
          return true;
        }
        return false;
      } catch (fileError: any) {
        console.warn(`Error reading AWS file ${filePath}:`, fileError.message);
        return false;
      }
    };

    if (readAndParseAWSFile(awsConfigPath, true)) {
      hasAnyProfiles = true;
    }
    if (readAndParseAWSFile(awsCredentialsPath, false)) {
      hasAnyProfiles = true;
    }

    if (!hasAnyProfiles || profiles.size === 0) {
      return [];
    }
    return Array.from(profiles).sort();
  } catch (error) {
    console.error('Error reading AWS profiles:', error);
    return [];
  }
};
